ac1.command:
set -u
A=docs/state/outputs/t99_definer_gate_amendment.json
test -f docs/state/merge_test_index.json || { echo "ac1 RED: docs/state/merge_test_index.json missing - run the fence from the repository root"; exit 1; }
command -v python3 >/dev/null || { echo "ac1 RED: python3 missing"; exit 1; }
test -f "$A" || { echo "ac1 RED: $A missing - t99 delivers a coordinated amendment RECORD and no merge candidate exists without it (the builder authors it; only the orchestrator applies it to the index)"; exit 1; }
python3 - "$A" <<'PYAC1' || exit 1
import hashlib, json, re, sys
A = sys.argv[1]
def fail(m):
    sys.stderr.write("ac1 RED: " + m + "\n"); raise SystemExit(1)
try:
    rec = json.load(open(A, encoding="utf-8"))
except ValueError as e:
    fail("%s is not parseable JSON (%s)" % (A, e))
HEX = re.compile(r"^[0-9a-f]{64}$")
if rec.get("card") != "t99":
    fail("the amendment record does not belong to card t99")
if rec.get("milestone") != "phase_15_gate_amendments":
    fail("record milestone is not phase_15_gate_amendments")
if str(rec.get("platform_issue")) != "105":
    fail("record platform_issue is not 105")
if rec.get("applied_by") != "orchestrator_in_strict_merge_window":
    fail("record must declare applied_by orchestrator_in_strict_merge_window - the index is orchestrator-owned and no card branch applies it")
if rec.get("no_leg_deleted") is not True or rec.get("verifier_thresholds_touched") is not False:
    fail("record must declare no_leg_deleted true and verifier_thresholds_touched false")
stale = rec.get("stale_literal", ""); target = rec.get("target_literal", "")
if not (HEX.match(stale or "") and HEX.match(target or "")):
    fail("stale_literal and target_literal must each be one 64-hex digest")
if stale == target:
    fail("stale_literal equals target_literal - that is not an amendment")
idx = json.load(open("docs/state/merge_test_index.json", encoding="utf-8"))["tests"]
esha = lambda e: hashlib.sha256(json.dumps(e, separators=(",", ":")).encode("utf-8")).hexdigest()
csha = lambda c: hashlib.sha256(c.encode("utf-8")).hexdigest()
if sum(e["command"].count(stale) for e in idx) != 2:
    fail("the shipped index no longer carries the stale literal exactly twice - the amendment premise (measured at groom: exactly tests[190] and tests[191]) has drifted; STOP, do not guess bytes")
am = rec.get("amendments", [])
inds = sorted(int(a.get("index", -1)) for a in am)
if inds != [190, 191]:
    fail("the record must carry exactly the coordinated pair {190, 191}, found %s - one leg without the other is a half-amendment and the index would assert two different digests of tests[133]" % inds)
if len(am) != 2:
    fail("the coordinated set must be exactly two entries, found %d" % len(am))
for a in am:
    n = int(a["index"]); t = idx[n]
    if a.get("issue_id") != "t47":
        fail("tests[%d] is not recorded as issue_id t47" % n)
    if t["issue_id"] != "t47":
        fail("tests[%d] is not t47 in the shipped index - the record describes a different tree" % n)
    cmd = t["command"]
    if cmd.count(stale) != 1:
        fail("tests[%d] does not carry the stale literal exactly once in the shipped index" % n)
    if csha(cmd) != a.get("old_command_sha256"):
        fail("STALE AMENDMENT - tests[%d] stored command sha %s != record old_command_sha256 %s; request a re-groom amendment rather than guessing bytes" % (n, csha(cmd), a.get("old_command_sha256")))
    if esha(t) != a.get("entry_sha_before"):
        fail("tests[%d] stored entry_sha %s != record entry_sha_before %s" % (n, esha(t), a.get("entry_sha_before")))
    new = cmd.replace(stale, target)
    if csha(new) != a.get("new_command_sha256"):
        fail("tests[%d] the single substitution does not hash to the recorded new_command_sha256 - the apply is not predictable" % n)
    e2 = dict(t); e2["command"] = new
    if esha(e2) != a.get("entry_sha_after"):
        fail("tests[%d] substituted entry does not hash to the recorded entry_sha_after - the merge-window apply would land different bytes than the record promises" % n)
    if int(a.get("occurrences_replaced", -1)) != 1:
        fail("tests[%d] must record occurrences_replaced exactly 1" % n)
    if len(new) != len(cmd) or int(a.get("old_command_len", -1)) != len(cmd) or int(a.get("new_command_len", -1)) != len(new):
        fail("tests[%d] the substitution is not length-preserving or the recorded lengths do not match the shipped bytes" % n)
    if a.get("rebuild_verified") is not True or a.get("stored_command_recheck") is not True:
        fail("tests[%d] must declare rebuild_verified and stored_command_recheck" % n)
    nc = a.get("negative_control_matrix", [])
    if len(nc) < 5:
        fail("tests[%d] needs at least five measured negative-control legs, found %d" % (n, len(nc)))
    bad = [x.get("case") for x in nc if x.get("measured_rc") != x.get("expected_rc")]
    if bad:
        fail("tests[%d] ships negative controls whose measured_rc disagrees with expected_rc: %s" % (n, bad))
    named = [x for x in nc if "byte-pin entry 133 changed" in str(x.get("last_line", ""))]
    if not named:
        fail("tests[%d] carries no control leg naming the stderr line 'byte-pin entry 133 changed' - a control that does not name the pin line cannot prove the pin bites (review warning W4)" % n)
    pre = a.get("pre_existing_red_premises", [])
    joined = " ".join(str(x) for x in pre)
    if not pre:
        fail("tests[%d] must name its pre-existing RED premises verbatim - the ZERO-baseline-flip prediction is only honest while the other premises are named" % n)
    if n == 190 and "freeze-scope" not in joined:
        fail("tests[190] must name the freeze-scope drift premise (measured first RED line at groom: ac3 RED: freeze-scope drift is [...])")
    if n == 191 and "ac4 RED: README drifted" not in joined:
        fail("tests[191] must name the verbatim premise line 'ac4 RED: README drifted' (measured at groom)")
co = rec.get("coordination", {})
if co.get("generator_side_card") != "t100":
    fail("the record must name t100 as the generator-side half of the same anchor refresh")
if co.get("target_entry_sha_of_tests_133") != target:
    fail("the record's coordination target must be the shipped entry_sha of tests[133] itself")
mnr = rec.get("measured_unchanged_no_record_needed", {})
if mnr.get("other_legs_embedding_target_prefix12", 1) != 0:
    fail("the record must state the measured scan result: no leg other than 190/191 embeds the target digest prefix")
if mnr.get("legs_pinning_current_digests_of_133_190_191_204_216", [1]) != []:
    fail("the record must state the measured empty hit-set of other legs pinning current digests of {133,190,191,204,216}")
sys.stdout.write("ac1 evidence: coordinated set {190,191} (both t47), stale literal occurs exactly twice in the %d-entry index and once per leg, all four before/after digest pairs re-hash against the SHIPPED index bytes, %d negative-control legs all with measured_rc == expected_rc and each leg naming the byte-pin line, pre-existing premises named per leg\n" % (len(idx), sum(len(a["negative_control_matrix"]) for a in am)))
sys.stdout.write("ac1 GREEN: COORDINATED RECORD SOUND - %s names both target indices and both issue_ids, the exact old and new literals, one occurrence replaced per leg, and per-leg before/after command sha and entry_sha that all re-hash against the shipped index; the apply is orchestrator-side only\n" % A)
PYAC1

ac2.command:
set -u
A=docs/state/outputs/t99_definer_gate_amendment.json
test -f "$A" || { echo "ac2 RED: $A missing - the single-substitution proof lives in the record, not in prose"; exit 1; }
test -f docs/state/merge_test_index.json || { echo "ac2 RED: docs/state/merge_test_index.json missing - run the fence from the repository root"; exit 1; }
command -v python3 >/dev/null || { echo "ac2 RED: python3 missing"; exit 1; }
python3 - "$A" <<'PYAC2' || exit 1
import hashlib, json, sys
A = sys.argv[1]
def fail(m):
    sys.stderr.write("ac2 RED: " + m + "\n"); raise SystemExit(1)
rec = json.load(open(A, encoding="utf-8"))
idx = json.load(open("docs/state/merge_test_index.json", encoding="utf-8"))["tests"]
stale = rec.get("stale_literal", ""); target = rec.get("target_literal", "")
csha = lambda c: hashlib.sha256(c.encode("utf-8")).hexdigest()
if len(rec.get("amendments", [])) != 2:
    fail("the record must carry exactly two legs to prove a substitution for")
for a in rec["amendments"]:
    n = int(a["index"]); stored = idx[n]["command"]
    new = a.get("new_command")
    if not isinstance(new, str):
        fail("tests[%d] record carries no new_command bytes - a substitution proof cannot be asserted in prose" % n)
    if new.count(target) != 1:
        fail("tests[%d] the recorded new_command does not contain the target literal exactly once (found %d) - the amendment must be ONE substitution" % (n, new.count(target)))
    if new.count(stale) != 0:
        fail("tests[%d] the recorded new_command still contains the stale literal - the substitution is incomplete" % n)
    if stored.count(stale) != 1:
        fail("tests[%d] the stored command does not contain the stale literal exactly once" % n)
    if stored.count(target) != 0:
        fail("tests[%d] the stored command already carries the target literal - the premise (pre-amendment leg) does not hold" % n)
    if stored.replace(stale, target) != new:
        fail("tests[%d] the recorded new_command is NOT the stored command with exactly one stale->target substitution - something else moved" % n)
    if new.replace(target, stale) != stored:
        fail("tests[%d] the substitution is not lossless: reversing it does not recover the stored bytes" % n)
    if len(new) != len(stored):
        fail("tests[%d] the substitution is not length-preserving (%d -> %d)" % (n, len(stored), len(new)))
    d = [i for i in range(min(len(stored), len(new))) if stored[i] != new[i]]
    if not d:
        fail("tests[%d] the two commands are identical - there is no substitution to prove" % n)
    span = (d[0], d[-1] + 1)
    if span[1] - span[0] != 64:
        fail("tests[%d] the differing span is %d characters wide, not the 64 of one digest literal - the diff is scattered across more than one literal" % (n, span[1] - span[0]))
    if stored[span[0]:span[1]] != stale or new[span[0]:span[1]] != target:
        fail("tests[%d] the differing 64-character window is not exactly the stale literal becoming the target literal" % n)
    if stored[:span[0]] + stored[span[1]:] != new[:span[0]] + new[span[1]:]:
        fail("tests[%d] anything outside the 64-character window differs - the substitution moved other bytes" % n)
    if int(a.get("first_differing_offset", -1)) != d[0]:
        fail("tests[%d] the recorded first_differing_offset %s does not match the measured offset %d" % (n, a.get("first_differing_offset"), d[0]))
    if csha(new) != a.get("new_command_sha256"):
        fail("tests[%d] the recorded new_command bytes do not hash to the recorded new_command_sha256" % n)
    if csha(stored) != a.get("old_command_sha256"):
        fail("tests[%d] the stored bytes do not hash to the recorded old_command_sha256 - the proof describes a different tree" % n)
tot = sum(len(idx[int(a["index"])]["command"]) for a in rec["amendments"])
sys.stdout.write("ac2 evidence: both legs prove a single contiguous 64-character substitution at one recorded offset - stored.replace(stale,target) == new AND new.replace(target,stale) == stored AND the Hamming difference is exactly the 64 positions of the digest, over %d command characters\n" % tot)
sys.stdout.write("ac2 GREEN: SINGLE-SUBSTITUTION PROOF - for tests[190] and tests[191] the amended command IS the stored command with exactly one 6e9723e8->09cb7d9a literal swap and NOTHING ELSE moved, proven byte-for-byte against the shipped index in both directions (a relaxation would show up here as a diff wider than the digest, a residual stale literal, or a non-lossless reverse)\n")
PYAC2
